```python
import os
import sys
import pandas as pd
import numpy as np
from datetime import datetime, timedelta

# 设置路径以导入共享库
sys.path.insert(0, os.path.join(os.environ['WATER_RESOURCES_ROOT'], 'lib'))
from db import query, query_multi

def analyze_shouxihu_water_quality():
    """
    分析瘦西湖最近一个月的水质变化趋势
    """

    # 1. 查找瘦西湖水质测站
    # 注意：rvnm 可能为 NULL，所以用 stnm 和 rvnm 双匹配，且限定 sttp='WQ'
    station_sql = """
    SELECT stcd, stnm, rvnm
    FROM sl323.st_stbprp_b
    WHERE sttp = 'WQ'
      AND (stnm LIKE '%瘦西湖%' OR rvnm LIKE '%瘦西湖%')
    LIMIT 1
    """

    stations = query(station_sql)

    if not stations:
        return "错误：未找到名为'瘦西湖'的水质监测站 (sttp='WQ')。请检查站点名称或类型。"

    stcd = stations[0]['stcd']
    stnm = stations[0]['stnm']

    # 2. 查询最近30天的水质监测数据
    # 主要指标: dox (DO), codmn (CODMn), nh3n (NH3N), tp (TP), ph
    # 时间字段: spt
    end_time = datetime.now()
    start_time = end_time - timedelta(days=30)

    data_sql = """
    SELECT 
        spt,
        dox,
        codmn,
        nh3n,
        tp,
        ph
    FROM sl325.wq_pcp_d
    WHERE stcd = %s
      AND spt >= %s
      AND spt < %s
    ORDER BY spt ASC
    """

    params = (stcd, start_time.strftime('%Y-%m-%d %H:%M:%S'), end_time.strftime('%Y-%m-%d %H:%M:%S'))
    df = query(data_sql, params)

    if df is None or len(df) == 0:
        return f"测站 {stnm} ({stcd}) 在最近30天内无水质监测数据。"

    # 转换为 DataFrame 以便分析
    df = pd.DataFrame(df)
    df['spt'] = pd.to_datetime(df['spt'])

    # 确保数值列为数值类型
    numeric_cols = ['dox', 'codmn', 'nh3n', 'tp', 'ph']
    for col in numeric_cols:
        df[col] = pd.to_numeric(df[col], errors='coerce')

    # 3. 计算统计指标
    stats = {}
    for col in numeric_cols:
        stats[col] = {
            'mean': df[col].mean(),
            'min': df[col].min(),
            'max': df[col].max(),
            'std': df[col].std()
        }

    # 4. 水质等级评定 (单因子评价法 - 取最差等级)
    # 标准参考 GB 3838-2002 地表水环境质量标准
    def get_water_class(dox, codmn, nh3n, tp, ph):
        """
        根据单因子评价法确定水质类别
        返回最差类别 (1-5, 6代表劣V类)
        """
        classes = []

        # DO (mg/L)
        if pd.isna(dox):
            pass
        elif dox >= 7.5: classes.append(1)
        elif dox >= 6: classes.append(2)
        elif dox >= 5: classes.append(3)
        elif dox >= 3: classes.append(4)
        elif dox >= 2: classes.append(5)
        else: classes.append(6)

        # CODMn (mg/L)
        if pd.isna(codmn):
            pass
        elif codmn <= 2: classes.append(1)
        elif codmn <= 4: classes.append(2)
        elif codmn <= 6: classes.append(3)
        elif codmn <= 10: classes.append(4)
        elif codmn <= 15: classes.append(5)
        else: classes.append(6)

        # NH3N (mg/L)
        if pd.isna(nh3n):
            pass
        elif nh3n <= 0.15: classes.append(1)
        elif nh3n <= 0.5: classes.append(2)
        elif nh3n <= 1.0: classes.append(3)
        elif nh3n <= 1.5: classes.append(4)
        elif nh3n <= 2.0: classes.append(5)
        else: classes.append(6)

        # TP (mg/L)
        if pd.isna(tp):
            pass
        elif tp <= 0.02: classes.append(1)
        elif tp <= 0.1: classes.append(2)
        elif tp <= 0.2: classes.append(3)
        elif tp <= 0.3: classes.append(4)
        elif tp <= 0.4: classes.append(5)
        else: classes.append(6)

        # pH (无量纲)
        if pd.isna(ph):
            pass
        elif 6.5 <= ph <= 8.5: classes.append(1) # pH 1-5类均为6.5-8.5，通常不作为劣化因子，除非超出
        else: classes.append(6) # 超出范围视为劣V类或单独处理，这里简化为最差

        if not classes:
            return None

        # 单因子评价法：取最差等级
        return max(classes)

    df['water_class'] = df.apply(
        lambda row: get_water_class(row['dox'], row['codmn'], row['nh3n'], row['tp'], row['ph']), 
        axis=1
    )

    class_map = {1: 'Ⅰ类', 2: 'Ⅱ类', 3: 'Ⅲ类', 4: 'Ⅳ类', 5: 'Ⅴ类', 6: '劣Ⅴ类'}
    df['class_name'] = df['water_class'].map(class_map)

    # 5. 趋势分析 (简单线性回归斜率判断趋势)
    trends = {}
    for col in numeric_cols:
        if df[col].notna().sum() > 1:
            # 使用 x 为时间戳的整数表示，y 为指标值
            x = (df['spt'] - df['spt'].min()).dt.total_seconds()
            y = df[col]

            # 简单线性回归
            if len(x) > 1:
                slope, intercept = np.polyfit(x, y, 1)
                trends[col] = slope
            else:
                trends[col] = 0
        else:
            trends[col] = 0

    # 6. 汇总结果
    result = {
        'station_name': stnm,
        'station_code': stcd,
        'period': f"{start_time.strftime('%Y-%m-%d')} 至 {end_time.strftime('%Y-%m-%d')}",
        'data_points': len(df),
        'statistics': stats,
        'trends': trends,
        'water_quality_distribution': df['class_name'].value_counts().to_dict(),
        'latest_water_class': df['class_name'].iloc[-1] if not df.empty else None,
        'latest_values': df.iloc[-1].to_dict() if not df.empty else {}
    }

    return result

# 执行分析
result = analyze_shouxihu_water_quality()
print(result)
